  : '';

// System prompt (neg�cio espec�fico ou padr�o)
const defaultPrompt = `Voc� � um assistente da Vendly. Responda em portugu�s, de forma natural e amig�vel.
Nome do cliente: ${msg.pushName || 'cliente'}
